// Load cookies directly from file (Puppeteer custom scripts don't have access to $input.all())
const fs = require('fs');
let cookies = [];
try {
  cookies = JSON.parse(fs.readFileSync('/data/cookies.json', 'utf8'));
  if (!Array.isArray(cookies)) {
    cookies = cookies.cookies || [];
  }
} catch (e) {
  throw new Error('Failed to load cookies from /data/cookies.json: ' + e.message);
}

if (!Array.isArray(cookies) || cookies.length === 0) {
  throw new Error('Cookies array is empty or invalid.');
}

// Navigate to x.com first to establish domain
await $page.goto('https://x.com', { waitUntil: 'domcontentloaded' });

// Ensure cookies have correct domain
const cookiesWithDomain = cookies.map((cookie) => ({
  ...cookie,
  domain: cookie.domain || '.x.com',
  url: cookie.url || 'https://x.com'
}));

// Set cookies
await $page.setCookie(...cookiesWithDomain);

// Navigate to home feed
await $page.goto('https://x.com/home', { waitUntil: 'networkidle2' });

// Wait for tweets to load
await $page.waitForSelector('article[data-testid="tweet"]', { timeout: 20000 });

// Scroll to load more tweets
for (let i = 0; i < 4; i++) {
  await $page.evaluate(() => window.scrollBy(0, 800));
  await new Promise((r) => setTimeout(r, 1500));
}

// Scrape tweets
const tweets = await $page.$$eval('article[data-testid="tweet"]', (arts) =>
  arts.map((a) => {
    const text = a.querySelector('div[data-testid="tweetText"]')?.innerText || '';
    const link = a.querySelector('a[href*="/status/"]')?.href || '';
    // Extract ID without regex to avoid escaping issues
    let id = '';
    if (link) {
      const parts = link.split('/status/');
      if (parts[1]) {
        id = parts[1].split(/[/?]/)[0];
      }
    }
    return { text, url: link, id };
  })
);

// Return tweets with cookies attached
return tweets
  .slice(0, 50)
  .filter((t) => t.id)
  .map((t) => ({ json: { ...t, cookies } }));

