const fs = require('fs');
const https = require('https');
let key = '';
try {
  const c = JSON.parse(fs.readFileSync('/data/config.json', 'utf8'));
  key = (c && c.GROQ_API_KEY) ? String(c.GROQ_API_KEY) : '';
} catch (e) {}
if (!key) throw new Error('GROQ_API_KEY missing. Create /data/config.json with {"GROQ_API_KEY":"gsk_..."}. See docs/setup.md');
const tweets = $input.all().map((i) => i.json);
if (tweets.length === 0) return [];
const prompt = 'Classify which tweets are about AI, ML, or related tech news. Reply ONLY with a JSON array of 0-based indices. No other text.\n\n' +
  tweets.map((t, i) => i + ': ' + (t.text || '').replace(/\n/g, ' ')).join('\n');
const postData = JSON.stringify({
  model: 'llama-3.1-8b-instant',
  max_tokens: 300,
  temperature: 0,
  messages: [{ role: 'user', content: prompt }]
});
const data = await new Promise((resolve, reject) => {
  const req = https.request({
    hostname: 'api.groq.com',
    path: '/openai/v1/chat/completions',
    method: 'POST',
    headers: {
      'Authorization': 'Bearer ' + key,
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  }, (res) => {
    let body = '';
    res.on('data', (chunk) => { body += chunk; });
    res.on('end', () => {
      try { resolve(JSON.parse(body)); } catch (e) { reject(e); }
    });
  });
  req.on('error', reject);
  req.write(postData);
  req.end();
});
const raw = (data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) || '[]';
let indices = [];
try { indices = JSON.parse(raw); } catch (e) {}
if (!Array.isArray(indices)) indices = [];
return tweets.filter((_, i) => indices.includes(i)).map((t) => ({ json: t }));

const fs = require('fs');
