// Load items from file (Puppeteer custom scripts don't have access to $input.all())
const fs = require('fs');
let items = [];
try {
  items = JSON.parse(fs.readFileSync('/data/pendingReplies.json', 'utf8'));
} catch (e) {
  throw new Error('Failed to load pending replies: ' + e.message);
}
if (!Array.isArray(items) || items.length === 0) return [];

// Load cookies from file
let cookies = [];
try {
  cookies = JSON.parse(fs.readFileSync('/data/cookies.json', 'utf8'));
  if (!Array.isArray(cookies)) cookies = cookies.cookies || [];
} catch (e) {
  throw new Error('Failed to load cookies: ' + e.message);
}
if (!Array.isArray(cookies) || cookies.length === 0) {
  throw new Error('Cookies not found or invalid');
}

// Navigate to x.com first to establish domain
await $page.goto('https://x.com', { waitUntil: 'domcontentloaded' });

// Ensure cookies have correct domain
const cookiesWithDomain = cookies.map(cookie => ({
  ...cookie,
  domain: cookie.domain || '.x.com',
  url: cookie.url || 'https://x.com'
}));

// Set cookies
await $page.setCookie(...cookiesWithDomain);

const out = [];

for (const { url, replyText, id } of items) {
  try {
    // Navigate to tweet with less strict wait condition and retry logic
    let navigationSuccess = false;
    let attempts = 0;
    const maxAttempts = 3;

    while (!navigationSuccess && attempts < maxAttempts) {
      try {
        await $page.goto(url, { 
          waitUntil: 'domcontentloaded', 
          timeout: 30000
        });
        navigationSuccess = true;
      } catch (navError) {
        attempts++;
        if (attempts >= maxAttempts) {
          throw new Error('Navigation failed after ' + maxAttempts + ' attempts: ' + navError.message);
        }
        await new Promise(r => setTimeout(r, 3000));
      }
    }

    await new Promise(r => setTimeout(r, 3000));

    const currentUrl = $page.url();
    if (!currentUrl.includes('x.com') || currentUrl.includes('login') || currentUrl.includes('i/flow')) {
      throw new Error('Unexpected page: ' + currentUrl + '. May need to refresh cookies.');
    }

    let replyButton = null;
    const replySelectors = [
      'div[data-testid="reply"]',
      'button[data-testid="reply"]',
      '[aria-label*="Reply" i]',
      'button[aria-label*="Reply" i]',
      'div[role="button"][aria-label*="Reply" i]'
    ];

    for (const selector of replySelectors) {
      try {
        await $page.waitForSelector(selector, { visible: true, timeout: 8000 });
        replyButton = await $page.$(selector);
        if (replyButton) break;
      } catch (e) {
        continue;
      }
    }

    if (!replyButton) {
      replyButton = await $page.evaluateHandle(() => {
        const buttons = Array.from(document.querySelectorAll('div[role="button"], button'));
        return buttons.find(btn => btn.textContent && btn.textContent.toLowerCase().includes('reply'));
      });
    }

    if (!replyButton) {
      throw new Error('Reply button not found. Page might require login or have changed structure.');
    }

    await replyButton.click();
    await $page.waitForSelector('div[data-testid="tweetTextarea_0"], div[role="textbox"]', { visible: true, timeout: 10000 });

    const cleanReply = (replyText || '').replace(/^["']|["']$/g, '').trim();

    await $page.evaluate(() => {
      const textarea = document.querySelector('div[data-testid="tweetTextarea_0"], div[role="textbox"]');
      if (textarea) {
        textarea.focus();
        textarea.innerText = '';
        textarea.textContent = '';
      }
    });

    await $page.type('div[data-testid="tweetTextarea_0"], div[role="textbox"]', cleanReply, { delay: 50 });
    await new Promise(r => setTimeout(r, 1500));

    const postSelectors = [
      'div[data-testid="tweetButtonInline"]',
      'div[data-testid="tweetButton"]',
      'button[data-testid="tweetButton"]',
      '[data-testid="tweetButtonInline"]'
    ];

    let posted = false;
    for (const selector of postSelectors) {
      try {
        const postBtn = await $page.$(selector);
        if (postBtn) {
          const isVisible = await $page.evaluate((el) => {
            const rect = el.getBoundingClientRect();
            return rect.width > 0 && rect.height > 0 && window.getComputedStyle(el).display !== 'none';
          }, postBtn);
          if (isVisible) {
            await postBtn.click();
            posted = true;
            break;
          }
        }
      } catch (e) {
        continue;
      }
    }

    if (!posted) {
      throw new Error('Post button not found or not clickable');
    }

    await new Promise(r => setTimeout(r, 3000));
    out.push({ json: { id, url, replyText: cleanReply, posted: true } });
  } catch (e) {
    out.push({ json: { id, url, replyText, posted: false, error: String(e && e.message) } });
  }

  await new Promise((r) => setTimeout(r, 10000 + Math.random() * 20000));
}

return out;

